"use client";
/* Scrolly, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Scrolly(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("scrolly"); }, []);
  return React.createElement("piix-pal", { "pal": "scrolly", ...piixAttrs(props) });
}

export default Scrolly;
